import { listTool, pathTool, scalesTool } from '../../decision-book/families/index.mjs';

const step = (id, title, prompt) => ({ id, title, prompt });

export const gtProjectEvaluation = listTool({
  id: 'gt_project_evaluation',
  name: 'Project Evaluation',
  when: 'A finished project needs review of both its result and the way people experienced the work.',
  failureModes: [
    'Assessing only punctual delivery.',
    'Ignoring damaging team dynamics because the result was good.',
    'Converting the three questions into an invented weighted score.',
    'Crediting the result to effort alone, and missing the luck and help behind it.'
  ],
  steps: [
    step('review_two_dimensions', 'Review two dimensions', 'Consider the delivered result and the working process separately.'),
    step('use_three_tests', 'Use three tests', 'For each, discuss enjoyment, financial return and beneficial effect.'),
    step('name_the_luck_and_help', 'Name the luck and the help', 'Beside the work you put in, name the people, timing and chances that made the result possible.'),
    step('decide_what_to_repeat', 'Decide what to repeat', 'Repeat it only if at least one of the three comes out yes; write down your call and one thing to change.')
  ],
  exercise: 'Review one completed project within 30 minutes and identify what you would repeat or change.',
  pairsWell: ['after_action_review'],
  chart: {
    layout: 'checklist',
    groups: [{ id: 'fun', label: 'Fun' }, { id: 'money', label: 'Money' }, { id: 'impact', label: 'Impact' }],
    entry: 'What you found under this test, for the result or for how the work felt',
    minGroups: 3
  }
});

export const gtTransactionalModel = scalesTool({
  id: 'gt_transactional_model',
  name: 'The Transactional Model',
  when: 'You want to notice unmet psychological needs before sustained work drains your energy.',
  failureModes: [
    'Confusing the three needs with a fixed sum.',
    'Treating the sketch as a clinical test.',
    'Waiting for exhaustion before noticing what supports you.'
  ],
  steps: [
    step('take_a_snapshot', 'Take a snapshot', 'Rate how well structure, stimuli and recognition are being met, from zero to ten.'),
    step('name_the_need', 'Name the need', 'Choose one low area and identify a feasible way to support it.'),
    step('compare_over_time', 'Compare over time', 'Keep dated snapshots and look for recurring patterns rather than treating one score as a diagnosis.')
  ],
  exercise: 'Record two dated three-need snapshots this week and try one action for the lowest area.',
  pairsWell: ['gt_routines'],
  chart: {
    mode: 'axes',
    min: 0,
    layout: 'radar',
    dated: true,
    // Drawn from the top, clockwise: recognition above, structure lower right, stimuli lower left.
    scales: [{ id: 'recognition', label: 'Recognition' }, { id: 'structure', label: 'Structure' }, { id: 'stimuli', label: 'Stimuli' }]
  }
});

export const gtJournalling = pathTool({
  id: 'gt_journalling',
  name: 'Journalling',
  when: 'Difficult moments dominate your memory of a day that also contained worthwhile events.',
  failureModes: [
    'Writing vague praise instead of actual events.',
    'Using gratitude to deny something painful.',
    'Expecting an immediate change from a single entry.'
  ],
  steps: [
    step('look_back_concretely', 'Look back concretely', 'Think through the day or, in the morning, the preceding day.'),
    step('find_three_specifics', 'Find three specifics', 'Record three worthwhile moments, however small, without pretending difficulties did not happen.'),
    step('repeat', 'Repeat', 'Try the practice each evening for four weeks and observe what you notice.')
  ],
  exercise: 'Keep a three-item evening record for four weeks, including ordinary small successes.',
  pairsWell: ['gt_project_evaluation'],
  chart: {
    variant: 'stages',
    stages: [
      { id: 'review_the_day', label: 'Review the day' },
      { id: 'record_three_good_things', label: 'Record three good things' },
      { id: 'repeat_each_evening', label: 'Repeat each evening' }
    ]
  }
});

export const gtReversedEffort = pathTool({
  id: 'gt_reversed_effort',
  name: 'The Law of Reversed Effort',
  tier: 'lens',
  when: 'Repeated attempts are making a goal feel more remote and less useful.',
  failureModes: [
    'Calling every difficult goal counterproductive.',
    'Using surrender to avoid an ordinary solvable obstacle.',
    'Treating the suggested waiting interval as a universal rule.'
  ],
  steps: [
    step('inspect_the_pattern', 'Inspect the pattern', 'What evidence suggests that added effort is worsening this particular situation?'),
    step('release_the_pursuit', 'Release the pursuit', 'Redirect attention instead of escalating the same attempt.'),
    step('revisit_the_desire', 'Revisit the desire', 'After a substantial interval, ask whether the goal still matters and whether another route exists.')
  ],
  exercise: 'Pause one repeatedly unproductive pursuit and record when and why you will reconsider it.',
  pairsWell: ['gt_circle_of_influence'],
  chart: {
    variant: 'stages',
    stages: [
      { id: 'notice_counterproductive_effort', label: 'Notice counterproductive effort' },
      { id: 'step_away', label: 'Step away' },
      { id: 'reassess_later', label: 'Reassess later' }
    ]
  }
});

